from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); components=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); pts=[]
        while q:
          y,x=q.popleft(); pts.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx)); q.append((yy,xx))
        if len(pts)>=3:
          components.append((col,pts))
    # Treat substantial colored components as shape seeds. Their rectangular
    # footprints are repaired; isolated annotations outside them are erased.
    footprints=[]
    for col,pts in components:
      rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
      r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
      area=(r1-r0+1)*(c1-c0+1)
      if len(pts)>=3 and len(pts)/area>=0.48:
        footprints.append((col,r0,r1,c0,c1))
    for r in range(h):
      for c in range(w):
        matches=[(col,a,b,x,y) for col,a,b,x,y in footprints if a<=r<=b and x<=c<=y]
        if matches:
          # nearest footprint color when shapes' boxes touch/overlap
          col=min(matches,key=lambda z: min(abs(r-z[1]),abs(r-z[2]))+min(abs(c-z[3]),abs(c-z[4])))[0]
          out[r][c]=col
        else:
          out[r][c]=bg
    return out", "exit_code": 0, "error": null}
